# ejemplo/calculadora.py

def dividir(a, b):
    return a / b

def promedio(valores=[]):
    return sum(valores) / len(valores)

def procesar(numero):
    try:
        return int(numero)
    except:
        return 0

print(dividir(10, 0))

# ejemplo/usuarios.py

def buscar_usuario(usuarios, id):
    for usuario in usuarios:
        if usuario["id"] == id:
            return usuario

def ejecutar_codigo(codigo):
    return eval(codigo)

